from __future__ import annotations

import os
import subprocess
import time
import uuid
from pathlib import Path

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    def __init__(self, session_name: str | None = None, socket_path: str | None = None, *, create: bool = True):
        self.session_name = session_name or f"headless-{uuid.uuid4().hex[:10]}"
        self.socket_path = socket_path or f"/tmp/{self.session_name}.sock"
        self._closed = False
        if create:
            Path(self.socket_path).parent.mkdir(parents=True, exist_ok=True)
            self._tmux("new-session", "-d", "-s", self.session_name, "/bin/bash -i")
            self._wait_ready()

    @classmethod
    def attach(cls, session_name: str, socket_path: str):
        term = cls(session_name=session_name, socket_path=socket_path, create=False)
        term._tmux("has-session", "-t", session_name)
        return term

    def _tmux(self, *args: str, check: bool = True) -> subprocess.CompletedProcess[str]:
        return subprocess.run(
            ["tmux", "-S", self.socket_path, *args],
            check=check,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

    def _wait_ready(self) -> None:
        for _ in range(50):
            result = self._tmux("has-session", "-t", self.session_name, check=False)
            if result.returncode == 0:
                return
            time.sleep(0.02)
        raise RuntimeError("terminal session did not become ready")

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        if self._closed:
            raise RuntimeError("terminal is closed")
        literal: list[str] = []

        def flush() -> None:
            if literal:
                self._tmux("send-keys", "-t", self.session_name, "-l", "".join(literal))
                literal.clear()

        controls = {3: "C-c", 4: "C-d", 9: "Tab", 13: "Enter", 27: "Escape"}
        for char in keystrokes:
            code = ord(char)
            if char == "\n":
                flush()
                self._tmux("send-keys", "-t", self.session_name, "Enter")
            elif code in controls:
                flush()
                self._tmux("send-keys", "-t", self.session_name, controls[code])
            else:
                literal.append(char)
        flush()
        if wait_sec:
            time.sleep(wait_sec)

    def capture(self, start: int = -200) -> str:
        if self._closed:
            raise RuntimeError("terminal is closed")
        return self._tmux("capture-pane", "-p", "-S", str(start), "-t", self.session_name).stdout

    def close(self) -> None:
        if self._closed:
            return
        self._tmux("kill-session", "-t", self.session_name, check=False)
        self._closed = True
        try:
            os.unlink(self.socket_path)
        except FileNotFoundError:
            pass
